selected.compute:
options = read('/input/options')
result = []
for k in range(2, 5):
    for choice in combinations(options, k):
        ids = [x['id'] for x in choice]
        if valid(ids):
            result = ids
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if valid(current):
        result = current
    else:
        result = []
if not result:
    result = read('/output/selection') if exists('/output/selection') else []
if not exists('/output/selection'):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
